  et:{localTitle:'Salvesta Androidis',localDescription:'Oma seadme režiimis kasutab Studio Androidi süsteemset failivalijat. Salvestada saab seadmesse, allalaadimiste kausta, SD-kaardile või Androidile kättesaadavasse dokumenditeenusesse.',openTitle:'Ava käsikiri Androidis',openDescription:'Valige OMI käsikiri seadmest või Androidi failivalijas kuvatavast salvestusteenusest.',saveAs:'Salvesta teise asukohta',noFile:'Selles seansis pole dokumendi asukohta veel valitud.',targetSelected:'Dokumendi asukoht on selle seansi jaoks valitud.',androidProviderHint:'Google Drive, OneDrive, Dropbox, Nextcloud ja muud salvestusrakendused võivad siin ilmuda, kui nende installitud rakendus pakub Androidi dokumenditeenust.'},
  fi:{localTitle:'Tallenna Androidissa',localDescription:'Oman laitteen tilassa Studio käyttää Androidin järjestelmän tiedostonvalitsinta. Voit tallentaa laitteelle, Lataukset-kansioon, SD-kortille tai Androidin käytettävissä olevaan tiedostopalveluun.',openTitle:'Avaa käsikirjoitus Androidissa',openDescription:'Valitse OMI-käsikirjoitus laitteelta tai Androidin tiedostonvalitsimessa näkyvästä tallennuspalvelusta.',saveAs:'Tallenna toiseen sijaintiin',noFile:'Tässä istunnossa ei ole vielä valittu asiakirjan sijaintia.',targetSelected:'Asiakirjan sijainti on valittu tätä istuntoa varten.',androidProviderHint:'Google Drive, OneDrive, Dropbox, Nextcloud ja muut tallennussovellukset voivat näkyä täällä, jos niiden asennettu sovellus tarjoaa Android-tiedostopalvelun.'},
